Comparing All Final Models
In this last section, we will compare all final models on the test set using both RMSE and MAE (mean absolute error).

all_metrics &lt;- rbind(
  best_fit |&gt;
    collect_metrics() |&gt;
    mutate(Model = "MLR", .before = ".metric"),
  LASSO_final |&gt;
    collect_metrics() |&gt;
    mutate(Model = "LASSO", .before = ".metric"),
  tree_final |&gt;
    collect_metrics() |&gt;
    mutate(Model = "REGRESSION_TREE", .before = ".metric"),
  bag_final |&gt;
    collect_metrics() |&gt;
    mutate(Model = "BAGGED_TREE", .before = ".metric"),
  rf_final |&gt;
    collect_metrics() |&gt;
    mutate(Model = "RANDOM_FOREST", .before = ".metric")
)

all_metrics |&gt;
  filter(.metric %in% c("rmse", "mae")) |&gt; 
  arrange(.estimate)

